(({F:e})=>{e.push({code:"gl",week:{dow:1,doy:4},prevText:"Ant",nextText:"Seg",todayText:"Hoxe",yearText:"Ano",monthText:"Mes",weekTextLong:"Semana",weekTextShort:"Sm",dayText:"Día",listText:"Axenda",prevHint:"$0 antes",nextHint:"$0 seguinte",todayHint(e,t){return"day"===t?"Hoxe":("week"===t?"Esta":"Este")+" "+e.toLocaleLowerCase()},viewHint(e,t){return"Vista "+("week"===t?"da":"do")+" "+e.toLocaleLowerCase()},allDayText:"Todo\no día",moreLinkText:"máis",moreLinkHint(e){return`Amosar ${e} eventos máis`},noEventsText:"Non hai eventos para amosar",navLinkHint:"Ir ao $0",closeHint:"Pechar",eventsHint:"Eventos"})})(FullCalendar.Shared);